ep_msg_send.versaScript:
json_xml import *;
vdb import *;
http import *;
email import *;
crypto import *;
jwt import *;
time import *;
datetime import *;

let req = params;
let body = req.body ?? {};
let authCtx = req.auth ?? {};
let actor = str(authCtx.username ?? authCtx.sub ?? "system").trim();
if (actor == "") {
  actor = "system";
}
let dryRun = body.dryRun == true || req.dryRun == true;
let messageId = str(body.messageId ?? req.messageId ?? "").trim();

let messages = vdb.collection("messages");
let rows = [];
if (messageId != "") {
  let lookup = messages.find({messageId: {$eq: messageId}}, 1);
  rows = lookup.data ?? [];
}
if (leng(rows) == 0) {
  let target = str(body.target ?? req.target ?? "").trim();
  let channel = str(body.channel ?? req.channel ?? "email").trim();
  let payloadBody = type(body.body) == "object" ? body.body : {};
  if (target != "") {
    if (messageId == "") {
      messageId = crypto.uuid();
    }
    let draft = {messageId: messageId, channel: channel, target: target, body: payloadBody};
    rows = [draft];
  } else {
    let fallback = messages.find({}, 1);
    rows = fallback.data ?? [];
  }
}
if (leng(rows) == 0) {
  return {ok: false, statusCode: 404, reason: "No message is available to queue"};
}

let message = rows[0];
messageId = str(message.messageId ?? messageId).trim();
let channel = str(message.channel ?? body.channel ?? req.channel ?? "email").trim();
let target = str(message.target ?? body.target ?? req.target ?? "").trim();
if (target == "") {
  return {ok: false, statusCode: 400, reason: "target is required to queue notification", messageId: messageId};
}

let messageBody = type(message.body) == "object" ? message.body : {};
let nowTs = datetime.now().isoformat();
let jobId = crypto.uuid();
let job = {
  jobId: jobId,
  messageId: messageId,
  channel: channel,
  target: target,
  payload: messageBody,
  status: "QUEUED",
  queuedAt: nowTs,
  queuedBy: actor
};

if (dryRun) {
  return {ok: true, dryRun: true, messageId: messageId, job: job};
}

let persistedMessage = true;
if (str(message.messageId ?? "").trim() == "") {
  let createRes = messages.insert({messageId: messageId, channel: channel, target: target, body: messageBody});
  if (createRes.ok == false) {
    return {ok: false, statusCode: 500, reason: createRes.error ?? "Failed to create message before queueing", messageId: messageId, result: createRes};
  }
} else {
  let updateRes = messages.update({messageId: {$eq: messageId}}, {deliveryStatus: "QUEUED", queuedAt: nowTs, queuedBy: actor});
  persistedMessage = updateRes.ok ?? false;
}

let queue = vdb.collection("notification_queue");
let queueRes = queue.insert(job);
if (queueRes.ok == false) {
  return {ok: false, statusCode: 500, reason: queueRes.error ?? "Failed to queue notification", messageId: messageId, jobId: jobId, result: queueRes};
}

return {ok: true, messageId: messageId, jobId: jobId, queued: true, channel: channel, target: target, persistedMessage: persistedMessage, queuedAt: nowTs};

